create index if not exists quote_settings_updated_by_idx on public.quote_settings(updated_by);
create index if not exists quote_discount_services_service_id_idx on public.quote_discount_services(service_id);
create index if not exists quotes_branch_id_idx on public.quotes(branch_id);
create index if not exists quotes_customer_id_idx on public.quotes(customer_id);
create index if not exists quotes_created_by_idx on public.quotes(created_by);
create index if not exists quote_items_quote_id_idx on public.quote_items(quote_id);
create index if not exists quote_items_service_id_idx on public.quote_items(service_id);
create index if not exists quote_items_professional_id_idx on public.quote_items(professional_id);
create index if not exists appointment_groups_branch_id_idx on public.appointment_groups(branch_id);
create index if not exists appointment_groups_customer_id_idx on public.appointment_groups(customer_id);
create index if not exists appointment_groups_quote_id_idx on public.appointment_groups(quote_id);
create index if not exists appointment_groups_created_by_idx on public.appointment_groups(created_by);
create index if not exists appointment_group_items_group_id_idx on public.appointment_group_items(appointment_group_id);
create index if not exists appointment_group_items_quote_item_id_idx on public.appointment_group_items(quote_item_id);
