drop policy if exists quote_settings_staff_all on public.quote_settings;
create policy quote_settings_staff_read on public.quote_settings for select to authenticated using (private.has_org_role(org_id,array['owner','admin','manager','receptionist']));
create policy quote_settings_manager_write on public.quote_settings for all to authenticated using (private.has_org_role(org_id,array['owner','admin','manager'])) with check (private.has_org_role(org_id,array['owner','admin','manager']));
drop policy if exists quote_discount_services_staff_all on public.quote_discount_services;
create policy quote_discount_services_staff_read on public.quote_discount_services for select to authenticated using (private.has_org_role(org_id,array['owner','admin','manager','receptionist']));
create policy quote_discount_services_manager_write on public.quote_discount_services for all to authenticated using (private.has_org_role(org_id,array['owner','admin','manager'])) with check (private.has_org_role(org_id,array['owner','admin','manager']));
